fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    let n = list.len();
    // k is 1-based; convert to 0-based index
    let idx_to_remove = k - 1;

    let mut new_list = Vec::with_capacity(n - 1);

    // Push all elements before the removal index
    new_list.extend_from_slice(&list[0..idx_to_remove]);

    // Push all elements after the removal index
    new_list.extend_from_slice(&list[(idx_to_remove + 1)..n]);

    new_list
}